type NegRiskEventsClockKey struct {
	ID common.Hash
}

func NewNegRiskEventsClockKey(value MemoryNegRiskEvent) NegRiskEventsClockKey {
	return NegRiskEventsClockKey{ID: value.ID}
}

type NegRiskEventsClockEntry struct {
	key        NegRiskEventsClockKey
	value      MemoryNegRiskEvent
	referenced uint32
	inUse      uint32
}

type NegRiskEventsClockCache struct {
	buckets  []int32
	next     []int32
	ring     []NegRiskEventsClockEntry
	mask     uint32
	capacity uint64
	hand     uint64
	size     uint64
	// evictions counts entries overwritten by CLOCK replacement. While zero,
	// the hot ring still holds everything ever Set — so under an authoritative
	// (from-genesis) run, hot contents are a superset of the entity's
	// ClickHouse rows and a hot miss proves a database miss.
	evictions uint64
	// cold is an optional Pebble-backed tier holding evicted entries (raw bytes).
	// nil unless attached via HotState.EnableColdCache (pointer-free entities only).
	cold *coldcache.Store
}

func NewNegRiskEventsClockCache(capacity uint64) *NegRiskEventsClockCache {
	if capacity == 0 {
		capacity = DefaultClockCacheCapacity
	}
	bucketCount := uint64(8)
	for bucketCount < capacity*2 {
		bucketCount <<= 1
	}
	c := &NegRiskEventsClockCache{
		ring:     make([]NegRiskEventsClockEntry, capacity),
		buckets:  make([]int32, bucketCount),
		next:     make([]int32, capacity),
		mask:     uint32(bucketCount - 1),
		capacity: capacity,
	}
	for i := range c.buckets {
		c.buckets[i] = -1
	}
	for i := range c.next {
		c.next[i] = -1
	}
	return c
}

func (c *NegRiskEventsClockCache) keyHash(key NegRiskEventsClockKey) uint32 {
	h := uint64(1469598103934665603)
	h = clockHash64(h, key.ID[:])
	return uint32(h^(h>>32)) & c.mask
}

func (c *NegRiskEventsClockCache) idxLookup(key NegRiskEventsClockKey) (uint64, bool) {
	for i := c.buckets[c.keyHash(key)]; i >= 0; i = c.next[i] {
		if c.ring[i].key == key {
			return uint64(i), true
		}
	}
	return 0, false
}

func (c *NegRiskEventsClockCache) idxInsert(key NegRiskEventsClockKey, ringIdx uint32) {
	h := c.keyHash(key)
	c.next[ringIdx] = c.buckets[h]
	c.buckets[h] = int32(ringIdx)
}

func (c *NegRiskEventsClockCache) idxUnlink(key NegRiskEventsClockKey) {
	h := c.keyHash(key)
	prev := int32(-1)
	for i := c.buckets[h]; i >= 0; i = c.next[i] {
		if c.ring[i].key == key {
			if prev < 0 {
				c.buckets[h] = c.next[i]
			} else {
				c.next[prev] = c.next[i]
			}
			c.next[i] = -1
			return
		}
		prev = i
	}
}

func (c *NegRiskEventsClockCache) Set(value MemoryNegRiskEvent) {
	c.SetByKey(NewNegRiskEventsClockKey(value), value)
}

func (c *NegRiskEventsClockCache) SetByKey(key NegRiskEventsClockKey, value MemoryNegRiskEvent) {
	if idx, ok := c.idxLookup(key); ok {
		e := &c.ring[idx]
		if atomic.LoadUint32(&e.inUse) == 1 && e.key == key {
			e.value = value
			atomic.StoreUint32(&e.referenced, 1)
			return
		}
	}
	for {
		hand := atomic.AddUint64(&c.hand, 1)
		idx := (hand - 1) % c.capacity
		e := &c.ring[idx]
		if atomic.CompareAndSwapUint32(&e.inUse, 1, 0) {
			if atomic.LoadUint32(&e.referenced) == 1 {
				atomic.StoreUint32(&e.referenced, 0)
				atomic.StoreUint32(&e.inUse, 1)
				continue
			}
			atomic.AddUint64(&c.evictions, 1)
			c.idxUnlink(e.key)
			e.key = key
			e.value = value
			atomic.StoreUint32(&e.referenced, 0)
			c.idxInsert(key, uint32(idx))
			atomic.StoreUint32(&e.inUse, 1)
			return
		}
		if atomic.LoadUint32(&e.inUse) == 0 {
			if atomic.CompareAndSwapUint32(&e.inUse, 0, 2) {
				e.key = key
				e.value = value
				atomic.StoreUint32(&e.referenced, 0)
				c.idxInsert(key, uint32(idx))
				atomic.AddUint64(&c.size, 1)
				atomic.StoreUint32(&e.inUse, 1)
				return
			}
		}
	}
}

func (c *NegRiskEventsClockCache) Get(key NegRiskEventsClockKey) (MemoryNegRiskEvent, bool) {
	idx, ok := c.idxLookup(key)
	if !ok {
		return MemoryNegRiskEvent{}, false
	}
	e := &c.ring[idx]
	if atomic.LoadUint32(&e.inUse) == 1 && e.key == key {
		atomic.StoreUint32(&e.referenced, 1)
		return e.value, true
	}
	return MemoryNegRiskEvent{}, false
}

func (c *NegRiskEventsClockCache) GetByFields(id common.Hash) (MemoryNegRiskEvent, bool) {
	return c.Get(NegRiskEventsClockKey{ID: id})
}

func (c *NegRiskEventsClockCache) Delete(key NegRiskEventsClockKey) bool {
	idx, ok := c.idxLookup(key)
	if !ok {
		return false
	}
	e := &c.ring[idx]
	if atomic.CompareAndSwapUint32(&e.inUse, 1, 0) {
		if e.key == key {
			c.idxUnlink(key)
			e.key = NegRiskEventsClockKey{}
			e.value = MemoryNegRiskEvent{}
			atomic.StoreUint32(&e.referenced, 0)
			atomic.AddUint64(&c.size, ^uint64(0))
			return true
		}
		atomic.StoreUint32(&e.inUse, 1)
	}
	return false
}

func (c *NegRiskEventsClockCache) Range(fn func(NegRiskEventsClockKey, MemoryNegRiskEvent) bool) {
	if fn == nil {
		return
	}
	limit := atomic.LoadUint64(&c.hand)
	if limit > c.capacity {
		limit = c.capacity
	}
	for i := uint64(0); i < limit; i++ {
		e := &c.ring[i]
		if atomic.LoadUint32(&e.inUse) == 1 {
			if !fn(e.key, e.value) {
				return
			}
		}
	}
}

func (c *NegRiskEventsClockCache) AppendValues(dst []MemoryNegRiskEvent) []MemoryNegRiskEvent {
	if c == nil {
		return dst
	}
	if atomic.LoadUint64(&c.size) == 0 {
		return dst
	}
	limit := atomic.LoadUint64(&c.hand)
	if limit > c.capacity {
		limit = c.capacity
	}
	for i := 0; i < int(limit); i++ {
		e := &c.ring[i]
		if atomic.LoadUint32(&e.inUse) == 1 {
			dst = append(dst, e.value)
		}
	}
	return dst
}

func (c *NegRiskEventsClockCache) Len() uint64 {
	return atomic.LoadUint64(&c.size)
}

