func (s *HotState) Commit(ctx context.Context, conn *ch.Client, db string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if conn == nil {
		clear(s.dirtyConditions)
		clear(s.dirtyUserPositions)
		clear(s.dirtyMarkets)
		clear(s.dirtyNegRiskEvents)
		clear(s.dirtyFixedProductMarketMakers)
		return nil
	}
	hadWork := len(s.dirtyConditions) > 0 || len(s.dirtyUserPositions) > 0 || len(s.dirtyMarkets) > 0 || len(s.dirtyNegRiskEvents) > 0 || len(s.dirtyFixedProductMarketMakers) > 0
	if len(s.dirtyConditions) > 0 {
		batch := NewMemoryConditionBatch()
		for key := range s.dirtyConditions {
			if val, ok := s.Conditions.Get(key); ok {
				batch.Append(val)
			}
		}
		if err := batch.Insert(ctx, conn, db); err != nil {
			return err
		}
		clear(s.dirtyConditions)
	}
	if len(s.dirtyUserPositions) > 0 {
		batch := NewMemoryUserPositionBatch()
		for key := range s.dirtyUserPositions {
			if val, ok := s.UserPositions.Get(key); ok {
				batch.Append(val)
			}
		}
		if err := batch.Insert(ctx, conn, db); err != nil {
			return err
		}
		clear(s.dirtyUserPositions)
	}
	if len(s.dirtyMarkets) > 0 {
		batch := NewMemoryMarketBatch()
		for key := range s.dirtyMarkets {
			if val, ok := s.Markets.Get(key); ok {
				batch.Append(val)
			}
		}
		if err := batch.Insert(ctx, conn, db); err != nil {
			return err
		}
		clear(s.dirtyMarkets)
	}
	if len(s.dirtyNegRiskEvents) > 0 {
		batch := NewMemoryNegRiskEventBatch()
		for key := range s.dirtyNegRiskEvents {
			if val, ok := s.NegRiskEvents.Get(key); ok {
				batch.Append(val)
			}
		}
		if err := batch.Insert(ctx, conn, db); err != nil {
			return err
		}
		clear(s.dirtyNegRiskEvents)
	}
	if len(s.dirtyFixedProductMarketMakers) > 0 {
		batch := NewMemoryFixedProductMarketMakerBatch()
		for key := range s.dirtyFixedProductMarketMakers {
			if val, ok := s.FixedProductMarketMakers.Get(key); ok {
				batch.Append(val)
			}
		}
		if err := batch.Insert(ctx, conn, db); err != nil {
			return err
		}
		clear(s.dirtyFixedProductMarketMakers)
	}
	if hadWork {
		if err := conn.Do(ctx, ch.Query{Body: "SYSTEM FLUSH ASYNC INSERT QUEUE"}); err != nil {
			return err
		}
	}
	return nil
}
func (s *HotState) RestoreMemoryCondition(key ConditionsClockKey, value MemoryCondition, had bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if had {
		s.Conditions.SetByKey(key, value)
		s.dirtyConditions[key] = struct{}{}
		return
	}
	s.Conditions.Delete(key)
	delete(s.dirtyConditions, key)
}

